package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Adds a proof to the claim: not to a SETTLED or VOID claim. */
public class AddProof {
    public void apply(@Val Claim claim) throws InvalidClaimStatusException {
        claim.addProof();
    }
}
package net.officefloor.hq.app.claim;

/** Why a claim above the proof threshold is refused a settle or an approval while it has no proofs. */
final class ProofRequired {
    private ProofRequired() {}

    static final String MESSAGE = "A claim whose due is above the proof threshold needs a proof first";
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the proof added; the line ends with the claim's proofs count now. */
public class AuditClaimProofAdded {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_PROOF_ADDED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim) + " proofs=" + claim.getProofs());
    }
}
# Add a proof to a claim. A SETTLED or VOID claim is a 409 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.AddProof
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimProofAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
