        </span>{' '}
        <label>
          Review SLA days{' '}
          <input
            data-testid="setting-review-sla"
            inputMode="numeric"
            placeholder="none"
            value={fields.reviewSla}
            onFocus={() => touch('reviewSla')}
            onChange={(e) => change('reviewSla', e.target.value)}
          />
        </label>{' '}
        <span>
